async function generateCertificate(course_id) {
    console.log('Generando certificado del usuario.');

    try {
        /*const response = await fetch(`/certificate?course_id=${course_id}`, {
            method: 'GET',
            headers: {
                'Accept': 'application/json',
                'X-CSRF-TOKEN': document.querySelector('meta[name="csrf-token"]')?.getAttribute('content') || ''
            },
        });*/

        // Simulación de respuesta exitosa.
        const response = {
            ok: true,
            json: async () => ({ name: 'Karina Sayuri Díaz Martínez', course_name: 'JavaScript desde 0' }),
        };

        // Simulación de respuesta fallida.
        /*const response = {
            ok: false,
            json: async () => ({ message: 'El usuario no esta registrado a este curso.' }),
        };*/

        const data = await response.json(); 

        if (response.ok) {
            const { jsPDF } = window.jspdf; 

            const doc = new jsPDF({
                orientation: 'l',
                unit: 'mm',
                format: 'a4'
            });

            const imgData = "";

            doc.addImage(imgData, 'PNG', 0, 0, 297, 210);

            doc.setFont('helvetica', 'bold'); 

            doc.setFontSize(25);

            doc.setTextColor(255, 255, 255); 

            doc.text(`"${data.name}"`, 128, 115, { align: 'center' });

            doc.setFontSize(16);

            doc.text(`- - - - - ${data.course_name} - - - - -`, 128, 145, { align: 'center' });

            doc.setProperties({
                title: `Certificado de ${data.name}`,
                author: "CodeAcademyPro"
            });

            const blob = doc.output('blob');
            const url = URL.createObjectURL(blob);
            window.open(url, "_blank");

            return;
        }
        else {
            alert(data.message);
            return;
        }
    } catch (error) {
        console.error('Error al generar el certificado del usuario:', error);
        alert('Ocurrió un error al generar su certificado. Por favor, inténtelo de nuevo más tarde.');
        return;
    }
}